const expected = String($env.N8N_WEBHOOK_SECRET || '').trim();
if (expected) {
  const headers = ($input.first().json || {}).headers || {};
  const got = String(headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '').trim();
  if (got !== expected) throw new Error('Unauthorized: missing or invalid webhook secret');
}
return $input.all();

const body = ($input.first().json || {}).body || {};
const action = String(body.action || '').trim();
const allowed = new Set(['indexHealth', 'websiteExplain']);
const accessToken = String(body.access_token || '').trim();

if (!allowed.has(action)) {
  return [{ json: { ok: false, error: 'Unsupported Website action.' } }];
}
if (!accessToken) {
  return [{ json: { ok: false, error: 'Sign in to read website analytics.' } }];
}

// The browser token is deliberately forwarded only to the private agent
// container. That handler is the authority for workspace membership; n8n
// never trusts the workspace id in this body by itself.
const request = { ...body };
delete request.action;
delete request.access_token;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: `${$env.AGENT_BASE_URL}/api/agent/${action}`,
    headers: { Authorization: `Bearer ${accessToken}`, 'Content-Type': 'application/json' },
    body: request,
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: action === 'indexHealth' ? 600000 : 180000,
  });
  const payload = response?.body && typeof response.body === 'object'
    ? response.body
    : { ok: false, error: `The agent returned ${response?.statusCode || 'an empty response'}.` };
  return [{ json: payload }];
} catch (err) {
  return [{ json: { ok: false, error: `Could not reach the Website agent: ${String(err?.message || err).slice(0, 300)}` } }];
}
